fn is_happy(s: Vec<char>) -> bool {
    // A sequence shorter than 3 cannot be "happy"
    if s.len() < 3 {
        return false;
    }

    // Check every window of length 3 for pairwise distinct characters
    for w in s.windows(3) {
        if w[0] == w[1] || w[0] == w[2] || w[1] == w[2] {
            return false;
        }
    }

    true
}

#[cfg(test)]
mod tests {
    use super::is_happy;

    #[test]
    fn test_happy_sequences() {
        assert!(!is_happy(vec!['a', 'b']));             // too short
        assert!(is_happy(vec!['a', 'b', 'c']));         // all distinct
        assert!(is_happy("abcdefg".chars().collect())); // all 3‐windows distinct
    }

    #[test]
    fn test_unhappy_sequences() {
        // window "aba" has repeated 'a'
        assert!(!is_happy(vec!['a', 'b', 'a', 'c', 'd']));
        // window "xxx" all same
        assert!(!is_happy(vec!['x', 'x', 'x', 'y', 'z']));
        // window "aab" has repeated 'a'
        assert!(!is_happy("zaabc".chars().collect()));
    }
}